import idle.core.*;import idle.core.upgrades.*;import idle.core.darkmatter.*;import idle.core.achievements.*;import idle.core.save.*;import java.util.*;import java.nio.file.*;
public class ProbeCosts{public static void main(String[]args)throws Exception{Game g=new Game(SaveCodec.read(Files.readString(Path.of(args[0]))).state(),Upgrades.DEFAULT,Automations.DEFAULT,DarkUpgrades.DEFAULT,Achievements.DEFAULT,new Random(1));System.out.printf("bb=%d expl=%d pps=%s particles=%s atoms=%s elem=%d speed=%d gen=%d nextSeed=%s nextDensity=%s\n",g.bigBangs(),g.state().explosions(),g.productionPerSecond(),g.state().particles(),g.state().atoms(),g.discoveredElements(),g.levelOf("speed"),g.levelOf("generator"),g.darkCostOf("dark_seeds"),g.darkCostOf("dark_density"));for(Upgrade u:g.upgrades(Resource.PARTICLES))System.out.printf(" PART %s level=%d next=%s\n",u.id(),g.levelOf(u.id()),g.costOf(u.id()));for(Upgrade u:g.upgrades(Resource.ATOMS))System.out.printf(" ATOM %s level=%d next=%s\n",u.id(),g.levelOf(u.id()),g.costOf(u.id()));}}
